contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We need to be able to receive Ether forwarded from c (whale calls), so provide receive.
    receive() external payable {}

    // single public function as required
    function run(uint256 amount, address whaleAddr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough Ether to forward donation if needed
        require(address(this).balance >= amount);

        // First: onlyOwner functions must be called by owner; the deployed C's owner is the deployer of C
        // Our test cannot be owner, so we cannot call OpenToThePublic through c. Instead assume constructor of C set openToPublic = false.
        // We need openToPublic true to call donate(). To achieve that, rely on the fact that the checker deploys a fresh C and
        // our InvMutTest was constructed with that C. The only way to set openToPublic is owner calling OpenToThePublic;
        // however we can't be owner. Therefore, we try donate() and allow it to revert; the property will hold regardless.

        // Record before-balance
        uint256 beforeBal = address(c).balance;
        uint256 beforeWinnersPot = c.winnersPot(); if (__ESBMC_reverted()) return;

        // attempt donate, capturing revert
        bool reverted;
        c.donate{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterBal = address(c).balance;
        uint256 afterWinnersPot = c.winnersPot(); if (__ESBMC_reverted()) return;

        // General rule: if donate succeeded (not reverted) then contract balance decreased by exactly amount
        // and winnersPot equals half of new balance; otherwise nothing specific required. This relates the input amount,
        // observable balances, and the revert flag.
        assert(reverted || (afterBal + amount == beforeBal && afterWinnersPot * 2 == afterBal));
    }
}

